#include <iostream>
#include <vector>
#include <string>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;
    std::string s;

    if (!(std::cin >> N)) return 0;
    std::cin >> s;

    std::vector<int> output;
    int current_length = 0;

    for (char c : s) {
        if (c == 'W') {
            if (current_length > 0) {
                output.push_back(current_length);
                current_length = 0;
            }
        } else {
            current_length++;
        }
    }
    if (current_length > 0) {
        output.push_back(current_length);
    }

    std::cout << output.size() << '\n';
    for (size_t i = 0; i < output.size(); ++i) {
        if (i > 0) std::cout << ' ';
        std::cout << output[i];
    }
    std::cout << '\n';

    return 0;
}

