#include <iostream>
#include <vector>
#include <string>
#include <sstream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int N;
    std::cin >> N;
    std::string s;
    std::cin >> s;

    std::vector<int> output;
    std::stringstream ss(s);
    std::string segment;

    while (std::getline(ss, segment, 'W')) {
        if (!segment.empty()) {
            output.push_back(segment.length());
        }
    }

    std::cout << output.size() << '\n';
    for (size_t i = 0; i < output.size(); ++i) {
        if (i > 0) std::cout << ' ';
        std::cout << output[i];
    }
    std::cout << '\n';

    return 0;
}

